Here is a relaxed Sunday plan below Saturday's: breakfast on the terrace, a slow walk, an early lunch, and back at Casa Lumeira by 16:00 for the airport.

```svelte file=lib/SundayPlan.svelte
<script>
  import { Section, Action, List, ListRow } from 'design';
  import ForkKnife from 'phosphor-svelte/lib/ForkKnife';
  import BookmarkSimple from 'phosphor-svelte/lib/BookmarkSimple';

  let current = $state(0);
  let lunchBooked = $state(false);
  let saved = $state(false);

  const stops = [
    { label: 'Slow breakfast on the roof terrace', sub: 'Casa Lumeira · river view', time: '09:00' },
    { label: 'Check out, leave bags at the desk', sub: 'Check-out by 11:00', time: '10:45' },
    { label: 'Santa Luzia viewpoint', sub: 'Short walk uphill through Alfama', time: '11:15' },
    { label: 'Lunch at Casa Brasido', sub: 'Clams, bread, a glass of white', time: '12:30' },
    { label: 'Riverside walk at Ribeira das Naus', sub: 'Steps down to the water, sit in the sun', time: '14:00' },
    { label: 'Back to Casa Lumeira for bags', sub: 'Leave for the airport by metro, about 30 min', time: '16:00' }
  ];
</script>

<Section title="Sunday Plan" kicker="Day plan · Sun Nov 15">
  <List>
    {#each stops as stop, i}
      <ListRow
        index={i + 1}
        label={stop.label}
        sub={stop.sub}
        trailing={stop.time}
        current={current === i}
        onclick={() => (current = i)}
      />
    {/each}
  </List>
  <p class="m-meta">Flight leaves 18:40, so leaving at 16:00 keeps plenty of margin.</p>
  {#snippet actions()}
    <Action
      label={lunchBooked ? 'Lunch booked' : 'Book lunch'}
      sublabel={lunchBooked ? 'Sun 12:30 · Casa Brasido' : 'Casa Brasido · Sun 12:30'}
      icon={ForkKnife}
      primary={!lunchBooked}
      disabled={lunchBooked}
      onclick={() => (lunchBooked = true)}
    />
    <Action
      label={saved ? 'Plan saved' : 'Save plan'}
      icon={BookmarkSimple}
      disabled={saved}
      onclick={() => (saved = true)}
    />
  {/snippet}
</Section>
```

